package com.clock.wallpaper;
import android.app.*;import android.content.*;import android.view.KeyEvent;import java.util.*;
public class MusicAlarmReceiver extends BroadcastReceiver { @Override public void onReceive(Context c,Intent i){android.content.SharedPreferences p=c.getSharedPreferences("clock",0);if(!p.getBoolean("musicAlarm",false))return;Intent media=new Intent(Intent.ACTION_MEDIA_BUTTON);media.putExtra(Intent.EXTRA_KEY_EVENT,new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_MEDIA_PLAY));c.sendBroadcast(media);media.putExtra(Intent.EXTRA_KEY_EVENT,new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_MEDIA_PLAY));c.sendBroadcast(media);Calendar at=Calendar.getInstance();at.add(Calendar.DAY_OF_YEAR,1);at.set(Calendar.HOUR_OF_DAY,p.getInt("alarmHour",8));at.set(Calendar.MINUTE,p.getInt("alarmMinute",0));at.set(Calendar.SECOND,0);at.set(Calendar.MILLISECOND,0);PendingIntent pi=PendingIntent.getBroadcast(c,88,new Intent(c,MusicAlarmReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at.getTimeInMillis(),pi);}}
